// State interface
interface ATMState {
    void insertCard(ATM atm, Card card);
    void enterPIN(ATM atm, String pin);
    void selectWithdrawal(ATM atm, int amount);
    void dispenseCash(ATM atm);
    void ejectCard(ATM atm);
}

// Main ATM controller (Singleton)
class ATM {
    private static ATM instance;
    private ATMState currentState;
    private Card currentCard;
    private Account currentAccount;
    private final CashDispenser dispenser;
    private final BankServer bankServer;

    private ATM() {
        this.currentState = new IdleState(); // Start idle
        this.dispenser = new CashDispenser(Map.of(100, 50, 50, 100, 20, 200));
        this.bankServer = new BankServerImpl();
    }

    public static synchronized ATM getInstance() {
        if (instance == null) instance = new ATM();
        return instance;
    }

    public void setState(ATMState newState) { this.currentState = newState; }
    public void insertCard(Card card) { currentState.insertCard(this, card); }
    public void enterPIN(String pin) { currentState.enterPIN(this, pin); }
    public void withdraw(int amount) { currentState.selectWithdrawal(this, amount); }

    // Getters/setters for currentCard, currentAccount, dispenser, bankServer
}

record Card(String cardNumber, String cardHolderName) {}
record Account(String accountNumber, AccountType type, double balance) {}
enum AccountType { SAVINGS, CHECKING, CREDIT }

interface BankServer {
    Optional<Account> verifyPIN(Card card, String pin);
    boolean debitAccount(Account account, int amount);
}

