interface ATMState {
    void insertCard(ATM atm, Card card);
    void enterPIN(ATM atm, String pin);
    void selectWithdrawal(ATM atm, int amount);
    void dispenseCash(ATM atm);
    void ejectCard(ATM atm);
}

class IdleState implements ATMState {
    @Override
    public void insertCard(ATM atm, Card card) {
        System.out.println("Card inserted: " + card.cardNumber());
        atm.setCurrentCard(card);
        atm.setState(new CardInsertedState()); // Transition to next state
    }

    @Override
    public void enterPIN(ATM atm, String pin) {
        throw new IllegalStateException("Insert card first"); // Invalid operation
    }

    @Override
    public void selectWithdrawal(ATM atm, int amount) {
        throw new IllegalStateException("Insert card first");
    }

    @Override
    public void dispenseCash(ATM atm) {
        throw new IllegalStateException("No active transaction");
    }

    @Override
    public void ejectCard(ATM atm) {
        System.out.println("No card to eject");
    }
}

class CardInsertedState implements ATMState {
    private int failedAttempts = 0;

    @Override
    public void insertCard(ATM atm, Card card) {
        System.out.println("Card already inserted");
    }

    @Override
    public void enterPIN(ATM atm, String pin) {
        var account = atm.getBankServer().verifyPIN(atm.getCurrentCard(), pin);
        if (account.isPresent()) {
            atm.setCurrentAccount(account.get());
            atm.setState(new AuthenticatedState()); // Successful auth
        } else {
            failedAttempts++;
            if (failedAttempts >= 3) {
                System.out.println("Card locked. Ejecting.");
                atm.setState(new IdleState()); // Lock and reset
                atm.ejectCard();
            } else {
                System.out.println("Invalid PIN. Attempts left: " + (3 - failedAttempts));
            }
        }
    }

    @Override
    public void selectWithdrawal(ATM atm, int amount) {
        throw new IllegalStateException("Authenticate first");
    }

    @Override
    public void dispenseCash(ATM atm) {
        throw new IllegalStateException("No transaction selected");
    }

    @Override
    public void ejectCard(ATM atm) {
        System.out.println("Ejecting card");
        atm.setState(new IdleState());
    }
}

class AuthenticatedState implements ATMState {
    @Override
    public void selectWithdrawal(ATM atm, int amount) {
        if (amount > atm.getCurrentAccount().balance()) {
            System.out.println("Insufficient funds");
            return;
        }
        atm.setWithdrawalAmount(amount);
        atm.setState(new DispensingCashState()); // Move to dispensing
        atm.dispenseCash();
    }

    @Override
    public void ejectCard(ATM atm) {
        System.out.println("Transaction cancelled. Ejecting.");
        atm.setState(new IdleState());
    }

    // Other methods throw exceptions or do nothing
}

