class CashDispenser {
    private final TreeMap<Integer, Integer> inventory; // denomination -> count, sorted descending

    public CashDispenser(Map<Integer, Integer> initialInventory) {
        this.inventory = new TreeMap<>(Comparator.reverseOrder());
        this.inventory.putAll(initialInventory);
    }

    public Map<Integer, Integer> dispense(int amount) throws InsufficientCashException {
        // Pre-check: can we make exact change?
        if (!canMakeExactChange(amount)) {
            throw new InsufficientCashException("Cannot make exact change for " + amount);
        }

        var result = new HashMap<Integer, Integer>();
        int remaining = amount;

        for (var entry : inventory.entrySet()) {
            int denomination = entry.getKey();
            int available = entry.getValue();

            if (remaining == 0) break;

            int needed = remaining / denomination; // How many of this bill we'd ideally use
            int toDispense = Math.min(needed, available); // Can't use more than we have

            if (toDispense > 0) {
                result.put(denomination, toDispense);
                remaining -= denomination * toDispense;
                inventory.put(denomination, available - toDispense); // Update inventory
            }
        }

        if (remaining > 0) {
            // Rollback inventory changes
            result.forEach((denom, count) -> 
                inventory.put(denom, inventory.get(denom) + count));
            throw new InsufficientCashException("Cannot dispense exact amount");
        }

        return result; // Map of denomination -> count dispensed
    }

    private boolean canMakeExactChange(int amount) {
        // Simplified check: amount must be multiple of smallest denomination
        int smallest = inventory.lastKey(); // TreeMap sorted descending, last is smallest
        if (amount % smallest != 0) return false;

        // Full check would require dynamic programming to verify reachability
        int total = inventory.entrySet().stream()
            .mapToInt(e -> e.getKey() * e.getValue())
            .sum();
        return amount <= total; // At least have enough total cash
    }

    public void reload(Map<Integer, Integer> bills) {
        bills.forEach((denom, count) -> 
            inventory.merge(denom, count, Integer::sum));
    }
}

class InsufficientCashException extends Exception {
    public InsufficientCashException(String message) { super(message); }
}

class ATM {
    private final BankServer bankServer;
    private final AuditLogger auditLogger;
    private Timer sessionTimer;
    private static final int SESSION_TIMEOUT_MS = 30_000; // 30 seconds

    public void enterPIN(String pin) {
        try {
            var card = getCurrentCard();
            auditLogger.log("PIN_ATTEMPT", card.maskedNumber()); // Log attempt, not PIN

            var account = bankServer.verifyPIN(card, pin); // Verify immediately
            pin = null; // Discard PIN from memory
            System.gc(); // Suggest garbage collection (not guaranteed)

            if (account.isPresent()) {
                setCurrentAccount(account.get());
                setState(new AuthenticatedState());
                startSessionTimer(); // Start inactivity timeout
                auditLogger.log("AUTH_SUCCESS", card.maskedNumber());
            } else {
                handleFailedPIN();
            }
        } catch (Exception e) {
            auditLogger.log("AUTH_ERROR", e.getMessage());
            throw e;
        }
    }

    private void handleFailedPIN() {
        var state = (CardInsertedState) currentState;
        state.incrementFailedAttempts();

        if (state.getFailedAttempts() >= 3) {
            auditLogger.log("CARD_LOCKED", getCurrentCard().maskedNumber());
            bankServer.lockCard(getCurrentCard()); // Notify bank to lock
            ejectCard();
        } else {
            auditLogger.log("PIN_FAILED", getCurrentCard().maskedNumber());
        }
    }

    private void startSessionTimer() {
        sessionTimer = new Timer();
        sessionTimer.schedule(new TimerTask() {
            @Override
            public void run() {
                auditLogger.log("SESSION_TIMEOUT", getCurrentCard().maskedNumber());
                ejectCard(); // Auto-eject on timeout
                setState(new IdleState());
            }
        }, SESSION_TIMEOUT_MS);
    }

    public void resetSessionTimer() {
        if (sessionTimer != null) {
            sessionTimer.cancel();
            startSessionTimer(); // Restart on user activity
        }
    }
}

interface BankServer {
    Optional<Account> verifyPIN(Card card, String pin); // PIN sent encrypted over TLS
    void lockCard(Card card);
    boolean debitAccount(Account account, int amount);
}

class AuditLogger {
    public void log(String action, String cardNumber) {
        var timestamp = Instant.now().toString();
        var logEntry = String.format("%s | %s | %s", timestamp, action, cardNumber);
        // In production: append to tamper-evident log (write-once storage)
        System.out.println("[AUDIT] " + logEntry);
    }
}

record Card(String cardNumber) {
    public String maskedNumber() {
        return "****" + cardNumber.substring(cardNumber.length() - 4); // Show last 4 digits only
    }
}

// 1. State Pattern
interface ATMState {
    void withdraw(ATM atm, int amount);
}

class AuthenticatedState implements ATMState {
    @Override
    public void withdraw(ATM atm, int amount) {
        atm.executeCommand(new WithdrawCommand(atm, amount)); // Delegates to Command
        atm.setState(new DispensingCashState());
    }
}

// 2. Singleton Pattern
class ATM {
    private static ATM instance;
    private ATM() {} // Private constructor

    public static synchronized ATM getInstance() {
        if (instance == null) instance = new ATM();
        return instance;
    }
}

// 3. Strategy Pattern for Account Types
interface WithdrawalStrategy {
    boolean canWithdraw(int amount, double balance);
    int getDailyLimit();
}

class SavingsWithdrawalStrategy implements WithdrawalStrategy {
    @Override
    public boolean canWithdraw(int amount, double balance) {
        return amount <= 500 && amount <= balance; // $500 daily limit
    }
    public int getDailyLimit() { return 500; }
}

class CheckingWithdrawalStrategy implements WithdrawalStrategy {
    @Override
    public boolean canWithdraw(int amount, double balance) {
        return amount <= 1000 && amount <= balance; // Higher limit
    }
    public int getDailyLimit() { return 1000; }
}

record Account(String number, double balance, WithdrawalStrategy strategy) {
    public boolean canWithdraw(int amount) {
        return strategy.canWithdraw(amount, balance);
    }
}

// 4. Command Pattern
interface Command {
    void execute();
    void undo();
    String getAuditLog();
}

class WithdrawCommand implements Command {
    private final ATM atm;
    private final int amount;
    private boolean executed = false;

    public WithdrawCommand(ATM atm, int amount) {
        this.atm = atm;
        this.amount = amount;
    }

    @Override
    public void execute() {
        atm.getBankServer().debitAccount(atm.getCurrentAccount(), amount);
        atm.getDispenser().dispense(amount);
        executed = true;
    }

    @Override
    public void undo() {
        if (executed) {
            atm.getBankServer().creditAccount(atm.getCurrentAccount(), amount); // Rollback
        }
    }

    @Override
    public String getAuditLog() {
        return String.format("WITHDRAW %d from %s", amount, atm.getCurrentAccount().number());
    }
}

// 5. Facade Pattern (implicit in ATM class)
class ATM {
    public void withdraw(int amount) {
        // Hides complexity of state.withdraw() + command.execute() + dispenser coordination
        currentState.withdraw(this, amount);
    }
}
